<script setup>
import { computed, inject, ref, reactive, watch, nextTick } from 'vue'
import { useRoute, useRouter, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import { adminLinks,adminDetails,validateAdminProduct,orderTransitions } from '../../admin.js'
import { money } from '../../shop.js'
const {state,record}=inject('admin-demo'),route=useRoute(),router=useRouter()
const search=ref(''),status=ref('all'),notice=ref(''),errors=ref({}),form=ref(null),pending=ref(null),categoryName=ref(''),categoryEdit=ref(null),replacement=ref(''),reason=ref(''),stock=ref(''),stockId=ref(''),dirty=ref(false)
const draft=reactive({name:'',category:'',price:'',stock:''})
const title=computed(()=>[...adminLinks,...adminDetails].find(([name])=>name===route.name)?.[2]||'Administration')
const product=computed(()=>state.products.find(item=>String(item.id)===route.params.id))
const order=computed(()=>state.orders.find(item=>item.reference===route.params.reference))
const customer=computed(()=>state.customers.find(item=>String(item.id)===route.params.id))
const returned=computed(()=>state.returns.find(item=>item.reference===route.params.reference))
const message=computed(()=>state.messages.find(item=>String(item.id)===route.params.id))
const filteredProducts=computed(()=>state.products.filter(item=>item.name.toLowerCase().includes(search.value.toLowerCase())&&(status.value==='all'||(status.value==='published')===item.published)))
const filteredOrders=computed(()=>state.orders.filter(item=>`${item.reference} ${item.customer}`.toLowerCase().includes(search.value.toLowerCase())&&(status.value==='all'||item.status===status.value)))
const filteredCustomers=computed(()=>state.customers.filter(item=>`${item.name} ${item.email}`.toLowerCase().includes(search.value.toLowerCase())))
const filteredReturns=computed(()=>state.returns.filter(item=>item.reference.toLowerCase().includes(search.value.toLowerCase())&&(status.value==='all'||item.status===status.value)))
const filteredMessages=computed(()=>state.messages.filter(item=>item.subject.toLowerCase().includes(search.value.toLowerCase())&&(status.value==='all'||item.status===status.value)))
watch(()=>route.fullPath,()=>{search.value='';status.value='all';notice.value='';errors.value={};pending.value=null;categoryEdit.value=null;categoryName.value='';reason.value='';stock.value='';stockId.value='';Object.assign(draft,product.value?{name:product.value.name,category:product.value.category,price:String(product.value.price/100),stock:String(product.value.stock)}:{name:'',category:'',price:'',stock:''});dirty.value=false},{immediate:true})
onBeforeRouteLeave(()=>!dirty.value||window.confirm('Quitter sans enregistrer les modifications du produit ?'))
onBeforeRouteUpdate(()=>!dirty.value||window.confirm('Quitter sans enregistrer les modifications du produit ?'))
function announce(text){notice.value=text;record(text)}
async function saveProduct(){errors.value=validateAdminProduct(draft,state.categories.map(item=>item.name));if(Object.keys(errors.value).length){await nextTick();form.value?.querySelector('[aria-invalid=true]')?.focus();return}const values={name:draft.name.trim(),category:draft.category,price:Math.round(Number(draft.price.replace(',','.'))*100),stock:Number(draft.stock)};if(product.value)Object.assign(product.value,values);else state.products.push({...values,id:Math.max(...state.products.map(item=>item.id),0)+1,published:false});dirty.value=false;record('Produit enregistré dans l’aperçu');await router.push({name:'admin-products'})}
function request(action,label){pending.value={action,label};nextTick(()=>document.getElementById('admin-confirm')?.focus())}
function confirm(){const task=pending.value;pending.value=null;task?.action();nextTick(()=>document.getElementById('admin-heading')?.focus())}
function saveCategory(){const name=categoryName.value.trim();if(!name||name.length>60||state.categories.some(item=>item.id!==categoryEdit.value&&item.name.toLowerCase()===name.toLowerCase())){notice.value='Nom requis, unique, de 60 caractères maximum.';return}const category=state.categories.find(item=>item.id===categoryEdit.value);if(category){state.products.filter(item=>item.category===category.name).forEach(item=>item.category=name);category.name=name}else state.categories.push({id:Math.max(...state.categories.map(item=>item.id),0)+1,name});categoryName.value='';categoryEdit.value=null;announce('Catégorie enregistrée dans l’aperçu')}
function deleteCategory(category){const target=state.categories.find(item=>String(item.id)===replacement.value&&item.id!==category.id);if(state.products.some(item=>item.category===category.name)&&!target){notice.value='Choisissez une catégorie de réaffectation différente.';return}request(()=>{state.products.filter(item=>item.category===category.name).forEach(item=>item.category=target.name);state.categories=state.categories.filter(item=>item.id!==category.id);announce('Catégorie supprimée et produits réaffectés dans l’aperçu')},`Supprimer « ${category.name} » et réaffecter ses produits ?`)}
function adjustStock(){const item=state.products.find(item=>String(item.id)===stockId.value);if(!item||!/^\d{1,6}$/.test(stock.value)||!reason.value.trim()||reason.value.length>200){notice.value='Choisissez un produit, un stock entier de 0 à 999 999 et un motif de 1 à 200 caractères.';return}request(()=>{item.stock=Number(stock.value);announce(`Stock de ${item.name} ajusté à ${item.stock} : ${reason.value.trim()}`);reason.value=''},`Remplacer le stock de ${item.name} par ${stock.value} ?`)}
</script>
<template><section class="admin-content"><header class="admin-heading"><div><span class="eyebrow coral">GESTION · SIMULATION</span><h1 id="admin-heading" tabindex="-1">{{title}}</h1></div><RouterLink v-if="route.name==='admin-products'" class="button button-dark" :to="{name:'admin-product-create'}">Nouveau produit</RouterLink></header><p v-if="notice" class="admin-notice" role="status">{{notice}}</p><div v-if="pending" class="admin-confirm" role="group" aria-labelledby="admin-confirm-label"><p id="admin-confirm-label">{{pending.label}}</p><button id="admin-confirm" class="button button-dark" @click="confirm">Confirmer la simulation</button><button class="text-link" @click="pending=null;nextTick(()=>document.getElementById('admin-heading')?.focus())">Annuler</button></div>
<template v-if="route.name==='admin-dashboard'"><div class="admin-metrics"><RouterLink v-for="[name,label,value] in [['admin-products','Produits',state.products.length],['admin-orders','Commandes fictives',state.orders.length],['admin-stock','Stocks ≤ 3',state.products.filter(item=>item.stock<=3).length],['admin-messages','Messages nouveaux',state.messages.filter(item=>item.status==='Nouveau').length]]" :key="name" :to="{name}"><span>{{label}}</span><strong>{{value}}</strong></RouterLink></div><div class="admin-card"><h2>Votre atelier de gestion</h2><p>Explorez le catalogue, les ajustements motivés de stock et les commandes fictives. Les actions sont consignées dans le journal de cet aperçu.</p><RouterLink :to="{name:'admin-activity'}">Voir l’activité</RouterLink></div></template>
<template v-else-if="['admin-product-create','admin-product-edit'].includes(route.name)"><p v-if="route.name==='admin-product-edit'&&!product">Produit introuvable.</p><form v-else ref="form" class="admin-card admin-form" @submit.prevent="saveProduct" @input="dirty=true" @change="dirty=true" novalidate><label v-for="[key,label] in [['name','Nom'],['price','Prix en euros'],['stock','Stock']]" :key="key" :for="'admin-'+key">{{label}}<input :id="'admin-'+key" :aria-label="label" v-model="draft[key]" :maxlength="key==='name'?100:12" :inputmode="key==='name'?'text':'decimal'" :aria-invalid="Boolean(errors[key])" :aria-describedby="'error-'+key" required/><span :id="'error-'+key" class="field-error">{{errors[key]}}</span></label><label for="admin-category">Catégorie<select id="admin-category" v-model="draft.category" :aria-invalid="Boolean(errors.category)" aria-describedby="error-category"><option value="">Choisir</option><option v-for="item in state.categories" :key="item.id">{{item.name}}</option></select><span id="error-category" class="field-error">{{errors.category}}</span></label><p>Création en brouillon. Les photos et variantes réelles seront gérées après intégration de la médiathèque et du modèle de variantes sécurisé côté serveur.</p><button class="button button-dark">Enregistrer la simulation</button><RouterLink :to="{name:'admin-products'}">Annuler</RouterLink></form></template>
<template v-else-if="route.name==='admin-products'"><div class="admin-tools"><label>Rechercher un produit<input v-model="search" type="search" maxlength="100"/></label><label>Publication<select v-model="status"><option value="all">Tous</option><option value="published">Publié</option><option value="draft">Brouillon / archivé</option></select></label></div><div class="admin-table"><table><caption>{{filteredProducts.length}} produit(s) fictif(s)</caption><thead><tr><th>Produit</th><th>Prix</th><th>Stock</th><th>État</th><th>Actions</th></tr></thead><tbody><tr v-for="item in filteredProducts" :key="item.id"><td>{{item.name}}<small>{{item.category}}</small></td><td>{{money(item.price)}}</td><td>{{item.stock}}</td><td>{{item.published?'Publié':'Brouillon / archivé'}}</td><td><RouterLink :to="{name:'admin-product-edit',params:{id:item.id}}">Modifier</RouterLink><button @click="request(()=>{item.published=!item.published;announce('Publication modifiée dans l’aperçu')},`${item.published?'Archiver':'Publier'} ${item.name} dans l’aperçu ?`)">{{item.published?'Archiver':'Publier'}}</button></td></tr></tbody></table></div><p v-if="!filteredProducts.length">Aucun produit trouvé.</p></template>
<template v-else-if="route.name==='admin-categories'"><form class="admin-card admin-form" @submit.prevent="saveCategory"><label>Nom de catégorie<input v-model="categoryName" maxlength="60" required/></label><button class="button button-dark">{{categoryEdit?'Modifier':'Créer'}} la catégorie</button><label>Réaffecter avant suppression<select v-model="replacement"><option value="">Choisir la destination</option><option v-for="item in state.categories" :key="item.id" :value="String(item.id)">{{item.name}}</option></select></label></form><article v-for="(item,index) in state.categories" :key="item.id" class="admin-row"><strong>{{index+1}}. {{item.name}}</strong><span>{{state.products.filter(product=>product.category===item.name).length}} produits</span><button @click="categoryEdit=item.id;categoryName=item.name">Modifier</button><button :disabled="index===0" @click="state.categories.splice(index-1,0,...state.categories.splice(index,1));announce('Ordre des catégories modifié')">Monter</button><button @click="deleteCategory(item)">Supprimer</button></article></template>
<template v-else-if="route.name==='admin-stock'"><form class="admin-card admin-form" @submit.prevent="adjustStock"><label>Produit<select v-model="stockId"><option value="">Choisir</option><option v-for="item in state.products" :key="item.id" :value="String(item.id)">{{item.name}} · stock {{item.stock}}</option></select></label><label>Nouveau stock<input v-model="stock" inputmode="numeric" maxlength="6"/></label><label>Motif fictif<input v-model="reason" maxlength="200"/></label><button class="button button-dark">Simuler l’ajustement</button></form><h2>Alertes de stock</h2><p v-for="item in state.products.filter(item=>item.stock<=3)" :key="item.id">{{item.name}} · {{item.stock}} exemplaires</p><RouterLink :to="{name:'admin-activity'}">Historique des ajustements</RouterLink></template>
<template v-else-if="route.name==='admin-orders'"><div class="admin-tools"><label>Rechercher une commande<input v-model="search" type="search" maxlength="100"/></label><label>État<select v-model="status"><option value="all">Tous</option><option v-for="item in Object.keys(orderTransitions)" :key="item">{{item}}</option></select></label></div><article v-for="item in filteredOrders" :key="item.reference" class="admin-row"><RouterLink :to="{name:'admin-order',params:{reference:item.reference}}">{{item.reference}}</RouterLink><span>{{item.customer}} · {{item.status}}</span><strong>{{money(item.total)}}</strong></article><p v-if="!filteredOrders.length">Aucune commande trouvée.</p></template>
<template v-else-if="route.name==='admin-order'"><div v-if="order" class="admin-card"><h2>{{order.reference}}</h2><p>{{order.customer}} · {{money(order.total)}} · {{order.status}}</p><p>Commande fictive sans adresse ni paiement. Les changements ci-dessous ne modifient aucun achat réel.</p><button v-for="target in orderTransitions[order.status]" :key="target" class="button button-dark" @click="request(()=>{order.status=target;announce('État de commande simulé : '+target)},`Passer ${order.reference} à « ${target} » ?`)">{{target}}</button><p>Remboursement désactivé : aucune transaction Stripe associée.</p></div><p v-else>Commande introuvable.</p></template>
<template v-else-if="route.name==='admin-customers'"><label class="admin-search">Rechercher un client fictif<input v-model="search" type="search" maxlength="100"/></label><article v-for="item in filteredCustomers" :key="item.id" class="admin-row"><RouterLink :to="{name:'admin-customer',params:{id:item.id}}">{{item.name}}</RouterLink><span>{{item.email}}</span></article><p v-if="!filteredCustomers.length">Aucun client trouvé.</p></template>
<template v-else-if="route.name==='admin-customer'"><div v-if="customer" class="admin-card"><h2>{{customer.name}}</h2><p>{{customer.email}}</p><p>Profil entièrement fictif. Aucune donnée personnelle réelle.</p><RouterLink :to="{name:'admin-order',params:{reference:'EXEMPLE-001'}}">Voir la commande d’exemple</RouterLink></div><p v-else>Client introuvable.</p></template>
<template v-else-if="route.name==='admin-returns'"><div class="admin-tools"><label>Référence du retour<input v-model="search" type="search" maxlength="100"/></label><label>État<select v-model="status"><option value="all">Tous</option><option>Demandé</option><option>Accepté</option><option>Refusé</option><option>Reçu</option></select></label></div><article v-for="item in filteredReturns" :key="item.reference" class="admin-row"><RouterLink :to="{name:'admin-return',params:{reference:item.reference}}">{{item.reference}}</RouterLink><span>{{item.status}}</span></article><p v-if="!filteredReturns.length">Aucun retour trouvé.</p></template>
<template v-else-if="route.name==='admin-return'"><div v-if="returned" class="admin-card"><h2>{{returned.reference}}</h2><p>{{returned.reason}} · {{returned.status}}</p><button v-for="target in (returned.status==='Demandé'?['Accepté','Refusé']:returned.status==='Accepté'?['Reçu']:[])" :key="target" class="button button-dark" @click="request(()=>{returned.status=target;announce('Retour simulé : '+target)},`Passer le retour à « ${target} » ?`)">{{target}}</button><p>Aucun remboursement disponible sans transaction réelle et autorisation serveur.</p></div><p v-else>Retour introuvable.</p></template>
<template v-else-if="route.name==='admin-messages'"><div class="admin-tools"><label>Rechercher un message<input v-model="search" type="search" maxlength="100"/></label><label>Traitement<select v-model="status"><option value="all">Tous</option><option>Nouveau</option><option>Traité</option></select></label></div><article v-for="item in filteredMessages" :key="item.id" class="admin-row"><RouterLink :to="{name:'admin-message',params:{id:item.id}}">{{item.subject}}</RouterLink><span>{{item.status}}</span></article><p v-if="!filteredMessages.length">Aucun message trouvé.</p></template>
<template v-else-if="route.name==='admin-message'"><div v-if="message" class="admin-card"><h2>{{message.subject}}</h2><p>{{message.body}}</p><p>État : {{message.status}}</p><button :disabled="message.status==='Traité'" class="button button-dark" @click="message.status='Traité';announce('Message marqué traité dans l’aperçu')">Marquer comme traité</button><p>Aucune réponse envoyée ; l’envoi réel n’est pas intégré.</p></div><p v-else>Message introuvable.</p></template>
<template v-else-if="route.name==='admin-settings'"><form class="admin-card admin-form" @submit.prevent="announce('Paramètres fictifs enregistrés en mémoire')"><label>Nom de la boutique<input v-model="state.settings.name" maxlength="100" required/></label><label>Message de démonstration<input v-model="state.settings.notice" maxlength="200" required/></label><p>Aucun secret, clé Stripe ou paramètre d’infrastructure dans cette interface. Ces réglages ne modifient pas la boutique publique.</p><button class="button button-dark">Simuler l’enregistrement</button></form></template>
<template v-else><p v-if="!state.activity.length">Aucune activité dans cet aperçu.</p><ol class="admin-log"><li v-for="item in state.activity" :key="item.id"><time>{{item.date}}</time><p>{{item.action}}</p></li></ol><p>Journal local de démonstration, limité à 100 entrées. Aucun audit serveur réel.</p></template>
</section></template>
